    "sql": "CREATE TABLE IF NOT EXISTS \"simulation_answers\" (\n\t\"id\" uuid PRIMARY KEY DEFAULT gen_random_uuid() NOT NULL,\n\t\"simulation_attempt_id\" uuid NOT NULL,\n\t\"question_id\" uuid NOT NULL,\n\t\"selected_option_id\" uuid,\n\t\"is_correct\" boolean,\n\t\"answered_at\" timestamp with time zone DEFAULT now() NOT NULL,\n\t\"time_spent_seconds\" integer DEFAULT 0\n);\n--> statement-breakpoint\nALTER TABLE \"simulations\" ADD COLUMN IF NOT EXISTS \"type\" varchar(50) DEFAULT 'FIXED' NOT NULL;\n--> statement-breakpoint\nALTER TABLE \"simulations\" ADD COLUMN IF NOT EXISTS \"difficulty\" varchar(50) DEFAULT 'MEDIO';\n--> statement-breakpoint\nALTER TABLE \"simulations\" ADD COLUMN IF NOT EXISTS \"status\" varchar(50) DEFAULT 'published' NOT NULL;\n--> statement-breakpoint\nALTER TABLE \"simulations\" ADD COLUMN IF NOT EXISTS \"is_public\" boolean DEFAULT true NOT NULL;\n--> statement-breakpoint\nALTER TABLE \"simulations\" ADD COLUMN IF NOT EXISTS \"filter_config\" jsonb;\n--> statement-breakpoint\nALTER TABLE \"simulations\" ADD COLUMN IF NOT EXISTS \"created_by\" uuid;\n--> statement-breakpoint\nALTER TABLE \"simulations\" ADD COLUMN IF NOT EXISTS \"updated_at\" timestamp with time zone DEFAULT now() NOT NULL;\n--> statement-breakpoint\nALTER TABLE \"simulations\" ADD COLUMN IF NOT EXISTS \"published_at\" timestamp with time zone;\n--> statement-breakpoint\nALTER TABLE \"simulations\" ADD COLUMN IF NOT EXISTS \"archived_at\" timestamp with time zone;\n--> statement-breakpoint\nALTER TABLE \"simulation_questions\" ADD COLUMN IF NOT EXISTS \"points\" numeric(4, 2) DEFAULT '1.00' NOT NULL;\n--> statement-breakpoint\nALTER TABLE \"simulation_attempts\" ADD COLUMN IF NOT EXISTS \"status\" varchar(50) DEFAULT 'IN_PROGRESS' NOT NULL;\n--> statement-breakpoint\nALTER TABLE \"simulation_attempts\" ADD COLUMN IF NOT EXISTS \"submitted_at\" timestamp with time zone;\n--> statement-breakpoint\nALTER TABLE \"simulation_attempts\" ADD COLUMN IF NOT EXISTS \"marked_questions\" jsonb DEFAULT '[]'::jsonb NOT NULL;\n--> statement-breakpoint\nALTER TABLE \"simulation_attempts\" ADD COLUMN IF NOT EXISTS \"topic_breakdown\" jsonb;\n--> statement-breakpoint\nALTER TABLE \"simulation_attempts\" ADD COLUMN IF NOT EXISTS \"difficulty_breakdown\" jsonb;\n--> statement-breakpoint\nDO $$ BEGIN\n ALTER TABLE \"simulations\" ADD CONSTRAINT \"simulations_created_by_users_id_fk\" FOREIGN KEY (\"created_by\") REFERENCES \"public\".\"users\"(\"id\") ON DELETE set null ON UPDATE no action;\nEXCEPTION\n WHEN duplicate_object THEN null;\nEND $$;\n--> statement-breakpoint\nDO $$ BEGIN\n ALTER TABLE \"simulation_answers\" ADD CONSTRAINT \"simulation_answers_simulation_attempt_id_simulation_attempts_id_fk\" FOREIGN KEY (\"simulation_attempt_id\") REFERENCES \"public\".\"simulation_attempts\"(\"id\") ON DELETE cascade ON UPDATE no action;\nEXCEPTION\n WHEN duplicate_object THEN null;\nEND $$;\n--> statement-breakpoint\nDO $$ BEGIN\n ALTER TABLE \"simulation_answers\" ADD CONSTRAINT \"simulation_answers_question_id_questions_id_fk\" FOREIGN KEY (\"question_id\") REFERENCES \"public\".\"questions\"(\"id\") ON DELETE cascade ON UPDATE no action;\nEXCEPTION\n WHEN duplicate_object THEN null;\nEND $$;\n--> statement-breakpoint\nDO $$ BEGIN\n ALTER TABLE \"simulation_answers\" ADD CONSTRAINT \"simulation_answers_selected_option_id_question_options_id_fk\" FOREIGN KEY (\"selected_option_id\") REFERENCES \"public\".\"question_options\"(\"id\") ON DELETE set null ON UPDATE no action;\nEXCEPTION\n WHEN duplicate_object THEN null;\nEND $$;\n--> statement-breakpoint\nCREATE INDEX IF NOT EXISTS \"idx_simulations_contest\" ON \"simulations\" USING btree (\"contest_id\");\n--> statement-breakpoint\nCREATE INDEX IF NOT EXISTS \"idx_simulations_status\" ON \"simulations\" USING btree (\"status\");\n--> statement-breakpoint\nCREATE INDEX IF NOT EXISTS \"idx_simulations_type\" ON \"simulations\" USING btree (\"type\");\n--> statement-breakpoint\nCREATE INDEX IF NOT EXISTS \"idx_simulations_created_by\" ON \"simulations\" USING btree (\"created_by\");\n--> statement-breakpoint\nCREATE UNIQUE INDEX IF NOT EXISTS \"idx_sim_q_unique\" ON \"simulation_questions\" USING btree (\"simulation_id\",\"question_id\");\n--> statement-breakpoint\nCREATE INDEX IF NOT EXISTS \"idx_sim_q_sim\" ON \"simulation_questions\" USING btree (\"simulation_id\");\n--> statement-breakpoint\nCREATE INDEX IF NOT EXISTS \"idx_sim_q_question\" ON \"simulation_questions\" USING btree (\"question_id\");\n--> statement-breakpoint\nCREATE INDEX IF NOT EXISTS \"idx_sim_attempts_user\" ON \"simulation_attempts\" USING btree (\"user_id\");\n--> statement-breakpoint\nCREATE INDEX IF NOT EXISTS \"idx_sim_attempts_sim\" ON \"simulation_attempts\" USING btree (\"simulation_id\");\n--> statement-breakpoint\nCREATE INDEX IF NOT EXISTS \"idx_sim_attempts_status\" ON \"simulation_attempts\" USING btree (\"status\");\n--> statement-breakpoint\nCREATE UNIQUE INDEX IF NOT EXISTS \"idx_sim_ans_attempt_q\" ON \"simulation_answers\" USING btree (\"simulation_attempt_id\",\"question_id\");\n--> statement-breakpoint\nCREATE INDEX IF NOT EXISTS \"idx_sim_ans_attempt\" ON \"simulation_answers\" USING btree (\"simulation_attempt_id\");\n--> statement-breakpoint\nCREATE INDEX IF NOT EXISTS \"idx_sim_ans_question\" ON \"simulation_answers\" USING btree (\"question_id\");\n"
